+  }
+  if (!response.ok) {
+    throw new Error(`${options.method || "GET"} ${url} failed with ${response.status}: ${typeof body === "string" ? body : JSON.stringify(body)}`);
+  }
+  return body;
+}
+
+function ticketText(ticket) {
+  const parts = [];
+  for (const field of ["subject", "description", "body"]) {
+    if (ticket[field]) parts.push(String(ticket[field]));
+  }
+  const messages = ticket.messages || ticket.conversation || ticket.comments || [];
+  for (const message of messages) {
+    parts.push(String(message.body || message.text || message.content || ""));
+  }
+  return parts.filter(Boolean).join("'"\\n\");
+}
+
+function extractTickets(payload) {
+  if (Array.isArray(payload)) return payload;
+  for (const key of [\"tickets\", \"items\", \"data\", \"results\"]) {
+    if (Array.isArray(payload?.[key])) return payload[key];
+  }
+  throw new Error(\"Could not find an array of tickets in the tickets API response\");
+}
+
+async function summarize(ticket) {
+  const state = JSON.stringify({
+    id: ticket.id,
+    subject: ticket.subject || ticket.title || \"\",
+    status: ticket.status || \"\",
+    conversation: ticketText(ticket),
+  });
+
+  const response = await fetch(\"https://openrouter.ai/api/v1/chat/completions\", {
+    method: \"POST\",
+    headers: headers({
+      Authorization: "'`Bearer ${OPENROUTER_API_KEY}`,
+      "HTTP-Referer": process.env.APP_URL || "http://localhost",
+      "X-Title": "Support ticket summarizer",
+    }),
+    body: JSON.stringify({
+      model: OPENROUTER_MODEL,
+      temperature: 0.2,
+      messages: [
+        {
+          role: "system",
+          content:
+            "Write exactly one concise paragraph summarizing the support ticket. State the user'"'s issue, key details, actions taken, and current state. Do not add headings, bullet points, Markdown, quotes, or information absent from the ticket.\",
+        },
+        { role: \"user\", content: state },
+      ],
+    }),
+  });
+
+  const data = await fetchJson(\"https://openrouter.ai/api/v1/chat/completions\", response);
+  const summary = data.choices?.[0]?.message?.content?.trim();
+  if ("'!summary || summary.includes("'"\\n\")) {
+    throw new Error("'`Model did not return a single paragraph for ticket ${ticket.id}`);
+  }
+  return summary;
+}
+
+async function updateTicket(ticket, summary) {
+  const url = `${TICKETS_API_URL.replace(/'"\\/"'$/, "")}/${ticket.id}`;
+  await fetchJson(url, {
+    method: "PATCH",
+    headers: headers(),
+    body: JSON.stringify({ [SUMMARY_FIELD]: summary }),
+  });
+}
+
+async function main() {
+  const payload = await fetchJson(TICKETS_API_URL, { headers: headers() });
+  const tickets = extractTickets(payload);
+  let updated = 0;
+
+  for (const ticket of tickets) {
+    try {
+      const summary = await summarize(ticket);
+      await updateTicket(ticket, summary);
+      updated += 1;
+      console.log(`Updated ticket ${ticket.id}`);
+    } catch (error) {
+      console.error(`Failed ticket ${ticket.id}: ${error.message}`);
+    }
+  }
+
+  if (updated === 0 && tickets.length > 0) {
+    process.exitCode = 1;
+  }
+}
+
+main();
*** Add File: README.md
+# Support Ticket Summarizer
+
+`scripts/summarize-tickets.mjs` fetches support tickets from an HTTP API, asks an OpenRouter chat model for a one-paragraph summary, and writes the result back to each ticket.
+
+## Configuration
+
+Set these environment variables before running:
+
+- `OPENROUTER_API_KEY` (required): server-side OpenRouter key.
+- `TICKETS_API_URL` (required): list endpoint for tickets.
+- `TICKETS_API_TOKEN`: optional bearer token for the tickets API.
+- `OPENROUTER_MODEL`: optional model slug; defaults to `openai/gpt-4o-mini`.
+- `SUMMARY_FIELD`: optional ticket field to write; defaults to `summary`.
+- `APP_URL`: optional app URL sent with OpenRouter attribution.
+
+The script expects:
+
+- `GET /tickets` to return an array, or an object containing `tickets`, `items`, `data`, or `results`.
+- `PATCH /tickets/:id` to accept partial JSON.
+- Each ticket to contain a subject, description/body, and/or messages, comments, or conversation entries with `body`, `text`, or `content`.
+
+Adjust the endpoint format and update method if your ticket system differs.
+
+## Run
+
+```bash
+node scripts/summarize-tickets.mjs
+```
+
+Per-ticket failures are logged and skipped; the script exits nonzero only if every ticket fails.
