import http from 'node:http';
const tickets = [{ id: 'T1', subject: 'Login broken', description: 'Cannot log in after reset.' }];
http.createServer((req, res) => {
  let chunks = [];
  req.on('data', c => chunks.push(c));
  req.on('end', () => {
    const body = Buffer.concat(chunks).toString();
    if (req.method === 'GET' && req.url === '/tickets') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ tickets }));
    } else if (req.method === 'PATCH' && req.url === '/tickets/T1') {
      console.error('PATCH', body);
      res.writeHead(204); res.end();
    } else if (req.method === 'POST' && req.url === '/api/v1/chat/completions') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ choices: [{ message: { content: 'The user cannot log in after resetting their password, and support is investigating account authentication.' } }] }));
    } else { res.writeHead(404); res.end(); }
  });
}).listen(8877);
